(() => {
  'use strict';
  const STORAGE_KEY = 'trace-digital-case-v1';
  const STAGES = [
    ['briefing','Mission briefing'],['room','Evidence room'],['email','Email investigation'],['messages','Message investigation'],['logs','Security logs'],['password','Password puzzle'],['links','Suspicious links'],['suspects','Suspect investigation'],['board','Evidence board'],['reconstruction','Incident reconstruction'],['recommendations','Security recommendations'],['report','Final case report']
  ];
  const CASE_TOTAL = 200;
  const evidenceInfo = {
    email:{title:'Evidence A · Suspicious email',why:'Urgent language and an unfamiliar verification destination are consistent with phishing warning signs.',description:'An urgent account verification message was received at 8:42 AM.'},
    messages:{title:'Evidence F · Message context',why:'The conversation establishes context, but does not identify who performed the unfamiliar sign-in.',description:'Alex and Jordan discussed the message; no verified evidence links Jordan to the login.'},
    login:{title:'Evidence B · Unfamiliar sign-in',why:'The successful sign-in from a previously unrecognized browser and unfamiliar network requires investigation.',description:'A successful sign-in was recorded at 8:53 AM from an unfamiliar device and network.'},
    settings:{title:'Evidence C · Account settings activity',why:'Settings activity occurred after the unfamiliar sign-in and before the project file was accessed.',description:'Account security settings were viewed at 8:56 AM.'},
    file:{title:'Evidence D · Project file access',why:'The file access follows the unfamiliar sign-in and settings activity in the timeline.',description:'Science_Project_Final.pdf was accessed at 9:05 AM.'},
    response:{title:'Evidence E · Security response',why:'School IT revoked active sessions and reset the password to contain the incident.',description:'The account was secured by school IT at 9:12 AM.'},
    inbox:{title:'Email Inbox · Case record',why:'A suspicious email was received at 8:42 AM; inspect the email investigation for its indicators.',description:'One urgent account verification email is recorded in the inbox.'},
    account:{title:'Account Activity · Case record',why:'Account activity includes an unfamiliar sign-in and security settings view.',description:'An unfamiliar successful sign-in was recorded at 8:53 AM, followed by settings activity at 8:56 AM.'},
    records:{title:'File Access Records · Case record',why:'The project file was accessed after the unfamiliar sign-in.',description:'Science_Project_Final.pdf was opened at 9:05 AM.'},
    notes:{title:'Investigation Notes · Case record',why:'Preserve evidence, distinguish observations from assumptions, and avoid unsupported accusations.',description:'The fictional case records do not identify the person responsible or confirm the exact entry method.'}
  };
  const roomCategories = [
    {id:'inbox',icon:'✉',name:'Email Inbox',sub:'Incoming messages · 1 record'},
    {id:'messages',icon:'▤',name:'Messages',sub:'Student conversation · 8:47 AM'},
    {id:'account',icon:'⌁',name:'Account Activity',sub:'Sign-in and settings activity'},
    {id:'records',icon:'▧',name:'File Access Records',sub:'Project file · 9:05 AM'},
    {id:'notes',icon:'✎',name:'Investigation Notes',sub:'Case handling guidance'}
  ];
  const questions = {
    email:[
      {id:'email1',text:'What is the strongest indication that this email may be a phishing attempt?',opts:['It contains a greeting.','It creates urgency and pressures the recipient to verify their account through an unfamiliar link.','It was received in the morning.','It mentions a student account.'],key:1,points:10,explain:'Phishing messages often use urgency and deceptive links to trick people into revealing information.'},
      {id:'email2',text:'What should Alex do before interacting with the link?',opts:['Click immediately because the message says the account will be disabled.','Forward the email to friends.','Independently contact the school\'s official IT department and report the suspicious email.','Reply with the account password.'],key:2,points:10,explain:'Contact IT using a known, official channel. Do not use the unexpected link or share a password.'},
      {id:'email3',text:'Why is the sender\'s display name not enough to prove the email is genuine?',opts:['Display names can be misleading or imitated.','All emails received in the morning are fake.','Genuine IT departments never send emails.','Email addresses cannot be inspected.'],key:0,points:10,explain:'A display name can be chosen or imitated. Check the full address and verify unexpected requests independently.'}
    ],
    messages:[
      {id:'message1',text:'What does Jordan\'s message tell the investigator?',opts:['Jordan is definitely the attacker.','The suspicious email may have circulated among students, but the message alone does not identify the attacker.','The email is definitely genuine.','The unfamiliar login must have come from Jordan\'s device.'],key:1,points:10,explain:'The thread gives context only. It is not proof that Jordan caused the incident.'},
      {id:'message2',text:'What is the most reliable next step after receiving an unfamiliar account sign-in alert?',opts:['Ignore it.','Share the alert publicly.','Verify the activity through the school\'s official account security system and report anything unfamiliar.','Accuse the last person who messaged Alex.'],key:2,points:10,explain:'Review the alert through an official service and promptly report activity Alex does not recognize.'}
    ],
    logs:[
      {id:'log1',text:'Which event should receive the most immediate investigation?',opts:['Alex received an ordinary message.','A sign-in was successfully recorded from an unfamiliar device and network.','The project file has a name.','The account was secured by IT.'],key:1,points:10,explain:'A successful sign-in from an unfamiliar device and network is suspicious and should be verified.'},
      {id:'log2',text:'What can the investigator reasonably conclude from the successful unfamiliar login?',opts:['Jordan definitely logged in.','The account was accessed through an unfamiliar device or network, and the event requires investigation.','The email sender is automatically the attacker.','No account access occurred.'],key:1,points:10,explain:'The log records an unfamiliar access event, but it does not identify who performed it or how access began.'},
      {id:'log3',text:'Which additional information would be most useful for the investigation?',opts:['Alex\'s favourite subject.','The colour of Alex\'s school bag.','Verified login history, session details, and whether Alex recognizes the device and activity.','The number of students in Alex\'s class.'],key:2,points:10,explain:'Authorized login history and session details help verify whether Alex recognizes the activity.'}
    ],
    password:[
      {id:'pass1',text:'Which option is the best example of a secure password practice?',opts:['Use School123 for every account.','Use your name and birthday.','Use a long, unique password or passphrase for each account and store it securely in a password manager.','Share your password with classmates so they can help you remember it.'],key:2,points:10,explain:'Long, unique passwords reduce guessing and password-reuse risks. A password manager can store them safely.'},
      {id:'pass2',text:'Does adding a predictable symbol or repeating a simple pattern automatically make a password strong?',opts:['Yes, any symbol guarantees security.','No, predictable variations can still be easy to guess.','Yes, if the password contains the word school.','No password can ever be secure.'],key:1,points:10,explain:'Merely adding predictable characters does not necessarily create a strong password.'}
    ],
    links:[{id:'link1',text:'Which link should be treated as suspicious in this scenario?',opts:['Link A, because it uses an unfamiliar verification domain and appears in an urgent unexpected email.','Link B, because every HTTPS link is dangerous.','Link C, because timetables are always phishing attempts.','All links are automatically safe because they contain the word school.'],key:0,points:10,explain:'HTTPS alone does not prove a site is trustworthy. Independently navigate to a known official service instead of trusting an unexpected link.'}],
    suspects:[{id:'suspect1',text:'Which conclusion is most justified by the evidence currently available?',opts:['Jordan is guilty because Jordan discussed the email.','Taylor is guilty because Taylor understands computers.','Morgan is guilty because Morgan shared a screenshot.','An account compromise is suspected, but the available evidence does not establish the identity of the person responsible.'],key:3,points:15,explain:'The records support investigating a suspected compromise, but no available evidence establishes a person’s identity or guilt.'}],
    reconstruction:[
      {id:'recon1',text:'Based on the evidence, what is the most likely explanation for the incident?',opts:['The incident was caused by the project file\'s name.','The suspicious email may have been part of a phishing attempt associated with an account compromise, but the precise entry method is not proven by the available evidence.','Jordan is definitely responsible.','The account was never accessed.'],key:1,points:15,explain:'The timeline is consistent with a possible phishing-related account compromise, but does not prove the initial access method or identify a person.'},
      {id:'recon2',text:'Which statement best separates a confirmed observation from an unproven assumption?',opts:['The logs record an unfamiliar successful sign-in; the identity of the person who performed it remains unconfirmed.','The logs prove that Jordan clicked the email.','The email proves that a password was stolen.','Anyone who knows Alex is automatically a suspect.'],key:0,points:15,explain:'The unfamiliar successful sign-in is recorded. The actor’s identity and exact access method remain unconfirmed.'},
      {id:'recon3',text:'What is the most appropriate next investigative action?',opts:['Publicly accuse the most suspicious classmate.','Delete all records immediately.','Preserve relevant logs, verify the account activity with authorized school IT staff, and investigate the email and sign-in records.','Send the suspicious email to every student.'],key:2,points:10,explain:'Preserve evidence and let authorized school IT staff verify relevant records. Avoid public accusations or spreading the message.'}
    ]
  };
  const suspects = [
    {name:'Jordan Lee',role:'Alex’s classmate',initials:'JL',connection:'Discussed the suspicious email in a class conversation.',evidence:'Jordan warned Alex to verify the email with IT.',detail:'No evidence directly connects Jordan’s device to the unfamiliar login.',note:'The conversation is relevant context but does not prove Jordan caused the incident.'},
    {name:'Taylor Reed',role:'Student technology club member',initials:'TR',connection:'Knows basic computer security and has worked on school technology projects.',evidence:'No verified record connects Taylor to the login or the email.',detail:'Technical knowledge alone is not evidence of wrongdoing.',note:'Do not infer guilt from technical ability.'},
    {name:'Morgan Vale',role:'Student who shared a similar-looking account notification',initials:'MV',connection:'May have encountered a similar message.',evidence:'The shared screenshot has no verified sender details.',detail:'No verified device or account record links Morgan to the incident.',note:'A shared screenshot is not proof of authorship or guilt.'},
    {name:'Unknown external actor',role:'Unidentified person or automated actor',initials:'??',connection:'The unfamiliar sign-in may indicate access by someone other than Alex.',evidence:'The unfamiliar device and network require investigation, but the available logs do not identify the person.',detail:'The source of the sign-in remains unverified.',note:'This is a possible explanation, not a confirmed identity.'}
  ];
  const boardItems = [
    {id:'A',name:'Suspicious Email',desc:'An urgent account verification message was received at 8:42 AM.'},
    {id:'B',name:'Unfamiliar Sign-in',desc:'A successful sign-in was recorded at 8:53 AM from an unfamiliar device and network.'},
    {id:'C',name:'Account Settings Activity',desc:'Account security settings were viewed at 8:56 AM.'},
    {id:'D',name:'Project File Access',desc:'A school project file was accessed at 9:05 AM.'},
    {id:'E',name:'Security Response',desc:'The school IT team secured the account at 9:12 AM.'},
    {id:'F',name:'Message Context',desc:'A classmate discussed the email; this does not connect that person to the login.'},
    {id:'CTX',name:'Context — not proof of guilt',desc:'Use this category for contextual clues that do not identify an attacker.'}
  ];
  const requiredPairs = [['A','B'],['B','C'],['C','D'],['D','E'],['F','CTX']];
  const initialState = () => ({started:false,stage:0,completed:[],score:0,answers:{},evidence:[],roomInspected:[],boardConnections:[],boardSelected:null,boardChecked:false,boardAwarded:0,recommendationChoice:[],recommendationSubmitted:false,suspectReview:{},logChallenge:false,logOrder:[],logFeedback:'',feedback:{}});
  let state = loadState();
  function loadState(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return initialState();const saved=JSON.parse(raw);if(!saved||typeof saved!=='object'||Array.isArray(saved))return initialState();const clean=initialState();const requested=Array.isArray(saved.completed)?saved.completed.filter(i=>Number.isInteger(i)&&i>=0&&i<STAGES.length):[];for(let i=0;i<STAGES.length&&requested.includes(i);i++)clean.completed.push(i);clean.started=saved.started===true;clean.evidence=Array.isArray(saved.evidence)?[...new Set(saved.evidence.filter(id=>Object.prototype.hasOwnProperty.call(evidenceInfo,id)))]:[];clean.roomInspected=Array.isArray(saved.roomInspected)?[...new Set(saved.roomInspected.filter(id=>roomCategories.some(c=>c.id===id)))]:[];const savedAnswers=saved.answers&&typeof saved.answers==='object'?saved.answers:{};Object.values(questions).flat().forEach(q=>{const item=savedAnswers[q.id];if(item&&Number.isInteger(item.selected)&&item.selected>=0&&item.selected<q.opts.length)clean.answers[q.id]={selected:item.selected,correct:item.selected===q.key};});const pairs=Array.isArray(saved.boardConnections)?saved.boardConnections:[];clean.boardConnections=[...new Set(pairs.filter(key=>typeof key==='string'&&requiredPairs.some(pair=>connectionKey(...pair)===key)))];clean.boardSelected=boardItems.some(item=>item.id===saved.boardSelected)?saved.boardSelected:null;clean.boardChecked=saved.boardChecked===true;clean.boardAwarded=clean.boardChecked&&Number.isInteger(saved.boardAwarded)?Math.max(0,Math.min(clean.boardConnections.length*4,saved.boardAwarded)):0;clean.recommendationChoice=Array.isArray(saved.recommendationChoice)?[...new Set(saved.recommendationChoice.filter(n=>Number.isInteger(n)&&n>=1&&n<=6))].slice(0,3):[];clean.recommendationSubmitted=saved.recommendationSubmitted===true;clean.suspectReview=saved.suspectReview&&typeof saved.suspectReview==='object'?Object.fromEntries(Object.entries(saved.suspectReview).filter(([i,v])=>Number.isInteger(Number(i))&&Number(i)>=0&&Number(i)<suspects.length&&['Supported by evidence','Insufficient evidence','Requires further investigation'].includes(v))):{};clean.logChallenge=saved.logChallenge===true;clean.logOrder=Array.isArray(saved.logOrder)&&saved.logOrder.length===6&&new Set(saved.logOrder).size===6&&saved.logOrder.every(i=>Number.isInteger(i)&&i>=0&&i<6)?saved.logOrder:[];clean.logFeedback=typeof saved.logFeedback==='string'?saved.logFeedback:'';clean.feedback=saved.feedback&&typeof saved.feedback==='object'?saved.feedback:{};const questionPoints=Object.values(questions).flat().reduce((sum,q)=>sum+(clean.answers[q.id]?.correct?q.points:0),0);clean.score=Math.min(CASE_TOTAL,questionPoints+clean.boardAwarded+(clean.recommendationSubmitted?clean.recommendationChoice.filter(n=>[1,2,3].includes(n)).length*5:0));const unlocked=clean.completed.length;clean.stage=Number.isInteger(saved.stage)?Math.max(0,Math.min(unlocked,STAGES.length-1,saved.stage)):0;return clean;}catch{return initialState();}}
  function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{/* Storage can be unavailable in private browser modes. */}}
  const app=document.getElementById('app'), modalRoot=document.getElementById('modal-root');
  const escapeHTML=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const has=id=>state.evidence.includes(id);
  const formatScore=()=>Math.min(CASE_TOTAL,state.score);
  function percent(){return Math.round((formatScore()/CASE_TOTAL)*100);}
  function questionStats(){let total=0,correct=0;Object.values(questions).flat().forEach(q=>{if(state.answers[q.id]){total++;if(state.answers[q.id].correct)correct++;}});return {total,correct};}
  function stageProgress(){return Math.round((state.completed.length/STAGES.length)*100);}
  function shell(content){const active=state.started;return `${active?`<header class="topbar"><a class="brand" href="#" data-action="home" aria-label="TRACE home"><span class="brand-mark">T</span><span>TRACE <span class="muted">/ DIGITAL CASE</span></span></a><div class="dashboard"><div class="progress-wrap"><div class="progress-label"><span>CASE PROGRESS</span><span>${stageProgress()}%</span></div><div class="progress-track" aria-label="Case progress"><div class="progress-fill" style="width:${stageProgress()}%"></div></div></div><div class="metric"><strong>${formatScore()}<span class="muted"> / 200</span></strong><span>Score</span></div><div class="metric"><strong>${state.evidence.length}</strong><span>Evidence</span></div><div class="top-actions"><button class="btn small ghost" data-action="guide">Field guide</button><button class="btn small ghost" data-action="how">How to play</button></div></div></header>`:''}${content}`;}
  function render(){if(!state.started){renderCover();return;}if(state.stage>=STAGES.length)state.stage=STAGES.length-1;let body='';switch(STAGES[state.stage][0]){case'briefing':body=renderBriefing();break;case'room':body=renderRoom();break;case'email':body=renderEmail();break;case'messages':body=renderMessages();break;case'logs':body=renderLogs();break;case'password':body=renderPassword();break;case'links':body=renderLinks();break;case'suspects':body=renderSuspects();break;case'board':body=renderBoard();break;case'reconstruction':body=renderReconstruction();break;case'recommendations':body=renderRecommendations();break;case'report':body=renderReport();break;}app.innerHTML=shell(`${renderStageNav()}<div class="screen" key="${STAGES[state.stage][0]}">${body}</div>`);}
  function renderCover(){app.innerHTML=`<section class="cover"><div class="cover-inner"><div class="cover-mark" aria-hidden="true">T_</div><div class="eyebrow">STUDENT CYBER INVESTIGATION UNIT</div><h1><span>TRACE:</span><br>A DIGITAL CASE</h1><p class="cover-subtitle">Every click leaves a trace. Can you uncover the truth?</p><div class="button-row"><button class="btn primary" data-action="start">${state.started?'RESUME INVESTIGATION':'START INVESTIGATION'} <span aria-hidden="true">→</span></button><button class="btn" data-action="how">HOW TO PLAY</button><button class="btn ghost" data-action="guide">CYBERSECURITY FIELD GUIDE</button></div><p class="cover-note">FICTIONAL TRAINING CASE · NO REAL ACCOUNTS OR DATA</p></div></section>`;}
  function renderStageNav(){return `<nav class="stage-nav" aria-label="Investigation stages">${STAGES.map(([id,name],i)=>`<button class="stage-link ${i===state.stage?'current':''} ${state.completed.includes(i)?'done':''}" data-action="goto" data-stage="${i}" ${i>highestUnlocked()?'disabled':''} aria-current="${i===state.stage?'step':'false'}">${String(i+1).padStart(2,'0')} ${escapeHTML(name)}</button>`).join('')}</nav>`;}
  function highestUnlocked(){let n=0;while(state.completed.includes(n)&&n<STAGES.length-1)n++;return n;}
  function heading(kicker,title,desc){return `<div class="screen-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><span class="tag cyan">CASE TR-2048 · ${STAGES[state.stage][0]==='report'?'CLOSED':'OPEN'}</span></div>`;}
  function footerNav(prevLabel='← Previous stage',nextLabel='Continue →'){return `<div class="divider"></div><div class="button-row">${state.stage>0?`<button class="btn ghost" data-action="previous">${prevLabel}</button>`:''}<button class="btn primary" data-action="next">${nextLabel}</button></div>`;}
  function renderBriefing(){return `${heading('MISSION CONTROL / INTAKE','Mission briefing','Review the assignment before opening the digital evidence room.')}<div class="grid two"><section class="panel"><div class="eyebrow">CASE FILE</div><div class="grid two" style="margin-top:14px"><div><div class="tiny muted">CASE ID</div><strong class="case-id">TR-2048</strong></div><div><div class="tiny muted">CASE TYPE</div><strong>Suspected Account Compromise</strong></div><div><div class="tiny muted">STATUS</div><span class="tag warning">Investigation open</span></div><div><div class="tiny muted">AFFECTED USER</div><strong>Alex Morgan</strong></div><div><div class="tiny muted">AFFECTED SYSTEM</div><strong>School Student Portal</strong></div></div></section><section class="panel"><div class="panel-title"><span class="icon">⌁</span><h2>Incident briefing</h2></div><p>At 8:42 AM, Alex received an email claiming that their school account required urgent verification. Later that morning, the school's security system recorded an unfamiliar login. At 9:05 AM, a confidential school project file was accessed. The school IT team has secured the account and requested an investigation. Your task is to determine the most likely cause of the incident and recommend ways to prevent it from happening again.</p></section></div><section class="panel" style="margin-top:16px"><div class="panel-title"><span class="icon">◎</span><h2>Investigation objectives</h2></div><div class="grid three"><div><span class="tag cyan">01</span><p style="margin:10px 0 0">Identify the suspicious activity.</p></div><div><span class="tag cyan">02</span><p style="margin:10px 0 0">Collect and connect relevant digital evidence.</p></div><div><span class="tag cyan">03</span><p style="margin:10px 0 0">Reconstruct the incident and recommend security measures.</p></div></div><div class="callout" style="margin-top:19px">All people, accounts, messages, domains, and logs in this training case are fictional. No credentials are requested or transmitted.</div><div class="button-row" style="margin-top:20px"><button class="btn primary" data-action="next">BEGIN INVESTIGATION →</button><button class="btn ghost" data-action="guide">Open field guide</button></div></section>`;}
  function renderRoom(){const inspected=state.roomInspected.length;return `${heading('DIGITAL FORENSICS / EVIDENCE ROOM','Digital evidence room','Select a case category to inspect its record. You can return to this room and revisit the collected evidence at any time.')}<div class="evidence-layout"><section class="panel"><div class="panel-title"><span class="icon">▦</span><h2>Case sources</h2><span class="tag">${inspected} / 5 inspected</span></div><div class="grid two">${roomCategories.map(c=>`<article class="category-card"><div class="icon">${c.icon}</div><h3 style="margin:10px 0 3px">${escapeHTML(c.name)}</h3><p class="tiny muted">${escapeHTML(c.sub)}</p><button class="btn small" data-action="inspect-room" data-id="${c.id}">${state.roomInspected.includes(c.id)?'REVIEW RECORD':'INSPECT RECORD'} ${state.roomInspected.includes(c.id)?'↗':'→'}</button></article>`).join('')}</div></section><aside class="panel"><div class="panel-title"><span class="icon">◈</span><h2>Evidence collection</h2></div>${state.evidence.length?state.evidence.map(id=>`<div class="evidence-item"><div><h3>${escapeHTML(evidenceInfo[id].title)}</h3><p class="tiny muted" style="margin:0">${escapeHTML(evidenceInfo[id].description)}</p></div><span class="tag green">Logged</span></div>`).join(''):'<div class="empty-state">No evidence collected yet.<br>Inspect records and evidence as you proceed.</div>'}</aside></div><div class="callout" style="margin-top:17px">Evidence can be reviewed again from the case file. Keep observations separate from assumptions.</div><div class="button-row" style="margin-top:18px"><button class="btn primary" data-action="next" ${inspected<5?'disabled title="Inspect all five case categories to proceed"':''}>${inspected<5?`INSPECT ALL CATEGORIES (${inspected}/5)`:'CONTINUE TO EMAIL INVESTIGATION →'}</button></div>`;}
  function renderQuestionGroup(group){return questions[group].map(q=>renderQuestion(q)).join('');}
  function renderQuestion(q){const result=state.answers[q.id];return `<section class="panel question-card" data-question="${q.id}"><div class="eyebrow">KNOWLEDGE CHECK · ${q.points} POINTS</div><h2 class="question-title">${escapeHTML(q.text)}</h2><div class="choice-list">${q.opts.map((opt,i)=>`<button class="choice ${result?(i===q.key?'correct':(i===result.selected?'incorrect':'')):''}" data-action="answer" data-question="${q.id}" data-choice="${i}" ${result?'disabled':''}><span class="choice-key">${String.fromCharCode(65+i)}.</span><span>${escapeHTML(opt)}</span></button>`).join('')}</div>${result?`<div class="feedback ${result.correct?'success':'error'}" role="status"><strong>${result.correct?'Correct — +'+q.points+' points.':'Not quite — no points awarded.'}</strong> ${escapeHTML(result.correct?q.explain:`${q.explain} The best answer is ${String.fromCharCode(65+q.key)}.`)}</div>`:''}</section>`;}
  function renderEmail(){return `${heading('EVIDENCE A / EMAIL ANALYSIS','Email investigation','Inspect the message carefully before answering. Its visible link is display-only and cannot open a website.')}<div class="grid two"><section class="email-window"><div class="email-head"><div class="eyebrow">INBOX RECORD · 8:42 AM</div><div class="email-meta" style="margin-top:12px"><strong>From:</strong><span>School IT Support</span><strong>Email address:</strong><span class="mono">it-support@school-verify.example</span><strong>Time received:</strong><span>8:42 AM</span><strong>Subject:</strong><strong>URGENT: Your Student Account Will Be Disabled</strong></div></div><div class="email-body">Dear Alex,<br><br>Our system has detected an issue with your student account. Your account will be suspended in 15 minutes unless you verify your details immediately.<br><br>Use the link below to restore access.<br><br><span class="display-link">VERIFY YOUR ACCOUNT NOW → http://school-verify.example/login</span><br><br>Failure to act may result in permanent account restrictions.<br><br>School IT Support Team</div></section><aside class="panel"><div class="panel-title"><span class="icon">⚠</span><h2>Inspection notes</h2></div><p>The address is an illustrative reserved example domain used for this fictional game. Do not open or use it; this displayed link does not transmit data.</p><ul class="indicator-list"><li>Urgent language and a threat of account suspension.</li><li>Pressure to act within 15 minutes.</li><li>An unfamiliar sender domain.</li><li>A request to verify account details through an unexpected link.</li><li>A sender name does not prove the email is authentic.</li></ul><button class="btn small" data-action="collect" data-id="email" style="margin-top:15px">${has('email')?'EVIDENCE A COLLECTED ✓':'ADD EMAIL TO EVIDENCE'}</button></aside></div><div style="margin-top:17px">${renderQuestionGroup('email')}</div>${footerNav()}`;}
  function renderMessages(){return `${heading('EVIDENCE F / MESSAGE CONTEXT','Message investigation','Use the conversation as context, not as proof of anyone’s guilt.')}<div class="grid two"><section class="panel"><div class="panel-title"><span class="icon">▤</span><h2>Student message thread</h2><span class="tag">8:47 AM</span></div><div class="thread"><div class="bubble"><strong>Jordan · 8:47 AM</strong>Hey, did you get that account verification email too?</div><div class="bubble alex"><strong>Alex</strong>Yes. It says my account will be disabled.</div><div class="bubble"><strong>Jordan</strong>Someone in our class group said it was an official school update, but I haven't checked with IT.</div><div class="bubble alex"><strong>Alex</strong>I was worried I might lose access.</div><div class="bubble"><strong>Jordan</strong>Don't click anything yet. Let's check with the school IT department.</div></div><div class="notification" style="margin-top:16px"><strong>◉ SYSTEM NOTIFICATION · 8:51 AM</strong><br>Account security alert: A sign-in attempt was recorded from an unfamiliar device.</div></section><aside class="panel"><div class="panel-title"><span class="icon">i</span><h2>Context matters</h2></div><div class="callout warning">Jordan's message is not proof that Jordan caused the incident. The conversation is contextual evidence, not proof of guilt.</div><p style="margin-top:15px">The notification signals an unfamiliar sign-in attempt. Alex should confirm it through the school's official account security system and report activity they do not recognize.</p><button class="btn small" data-action="collect" data-id="messages">${has('messages')?'MESSAGE EVIDENCE COLLECTED ✓':'ADD THREAD TO EVIDENCE'}</button></aside></div><div style="margin-top:17px">${renderQuestionGroup('messages')}</div>${footerNav()}`;}
  const logs=[['8:42 AM','Suspicious email received.','Alex Morgan','Email delivered.'],['8:47 AM','Message about account verification.','Alex Morgan','Message received.'],['8:53 AM','Account sign-in recorded.','Alex Morgan','Device: Previously unrecognized browser · Location: Unfamiliar network · Sign-in successful.'],['8:56 AM','Account security settings viewed.','Alex Morgan','Access recorded.'],['9:05 AM','School project file accessed.','Alex Morgan','File: Science_Project_Final.pdf · File opened.'],['9:12 AM','Account secured by school IT.','Alex Morgan','Active sessions revoked and password reset.']];
  function renderLogs(){return `${heading('EVIDENCE B–E / EVENT REVIEW','Security log investigation','Review the fictional records in chronological order and separate observations from conclusions.')}<section class="panel"><div class="panel-title"><span class="icon">⌗</span><h2>Security event timeline</h2><span class="tag cyan">CHRONOLOGICAL</span></div><div class="button-row" style="margin:0 0 14px"><button class="btn small" data-action="log-challenge">${state.logChallenge?'RESET TO TIMELINE':'OPTIONAL SORT CHALLENGE'}</button>${state.logChallenge?`<button class="btn small primary" data-action="check-log-order">CHECK CHRONOLOGICAL ORDER</button>`:''}</div>${state.logChallenge?'<p class="tiny muted">Use the ↑ and ↓ buttons to place records in chronological order. This optional challenge does not affect your score.</p>':''}<div class="log-list">${(state.logChallenge&&state.logOrder.length?state.logOrder.map(index=>({entry:logs[index],index})):logs.map((entry,index)=>({entry,index}))).map(({entry:l,index:i},position)=>`<article class="log-entry"><div class="log-time">${l[0]}</div><div><h3>${escapeHTML(l[1])}</h3><p>User: ${escapeHTML(l[2])} · ${escapeHTML(l[3])}</p></div>${state.logChallenge?`<div class="button-row"><button class="btn small" data-action="move-log" data-position="${position}" data-direction="-1" aria-label="Move record up" ${position===0?'disabled':''}>↑</button><button class="btn small" data-action="move-log" data-position="${position}" data-direction="1" aria-label="Move record down" ${position===logs.length-1?'disabled':''}>↓</button></div>`:`<span class="tag ${i===2?'warning':i===5?'green':''}">${i===2?'Review':i===5?'Contained':'Record '+(i+1)}</span>`}</article>`).join('')}</div>${state.logFeedback?`<div class="feedback ${state.logFeedback.startsWith('Correct')?'success':'info'}" role="status">${escapeHTML(state.logFeedback)}</div>`:''}<div class="callout warning" style="margin-top:16px">These are fictional training records created for this game. A successful login from an unfamiliar device is suspicious, but it does not by itself prove who performed the login or exactly how the account was compromised.</div><div class="button-row" style="margin-top:16px"><button class="btn small" data-action="collect" data-id="login">${has('login')?'LOGIN RECORD COLLECTED ✓':'ADD LOGIN RECORD'}</button><button class="btn small" data-action="collect" data-id="settings">${has('settings')?'SETTINGS RECORD COLLECTED ✓':'ADD SETTINGS RECORD'}</button><button class="btn small" data-action="collect" data-id="file">${has('file')?'FILE RECORD COLLECTED ✓':'ADD FILE ACCESS RECORD'}</button><button class="btn small" data-action="collect" data-id="response">${has('response')?'RESPONSE COLLECTED ✓':'ADD IT RESPONSE'}</button></div></section><div style="margin-top:17px">${renderQuestionGroup('logs')}</div>${footerNav()}`;}
  function renderPassword(){return `${heading('SECURITY LAB / PASSWORDS','Password security puzzle','Spot safer password habits and test your reasoning about predictable patterns.')}<div class="grid two"><section class="panel"><div class="panel-title"><span class="icon">▣</span><h2>Build better habits</h2></div><p>A strong password should be long, unique, difficult to guess, and not reused across accounts. A password manager can help users create and store unique passwords.</p><div class="callout">Use a different password for each account. Never share it with classmates or enter it into an unexpected page.</div><div style="margin-top:16px">${renderQuestion(questions.password[0])}</div></section><section class="panel"><div class="panel-title"><span class="icon">⌘</span><h2>Pattern check</h2></div><p class="muted">Consider this sequence:</p><div class="grid three" style="gap:8px"><div class="tag">school123</div><div class="tag">school123!</div><div class="tag">school123!!</div></div><p style="margin-top:17px">A predictable variation can still be guessed. Length and uniqueness matter more than adding one obvious symbol.</p>${renderQuestion(questions.password[1])}</section></div>${footerNav()}`;}
  function renderLinks(){return `${heading('SECURITY LAB / LINK ANALYSIS','Suspicious link challenge','Inspect the fictional destinations in context. These are display-only examples and do not link to real services.')}<section class="panel"><div class="grid three"><article class="category-card"><div class="eyebrow">LINK A</div><h3>School Account Verification</h3><div class="display-link">http://school-verify.example/login</div><span class="tag warning" style="margin-top:12px">Unexpected domain</span></article><article class="category-card"><div class="eyebrow">LINK B</div><h3>School Portal</h3><div class="display-link" style="color:var(--cyan2);border-color:var(--cyan)">https://portal.school.example/account</div><span class="tag">Fictional example</span></article><article class="category-card"><div class="eyebrow">LINK C</div><h3>Class Timetable</h3><div class="display-link" style="color:var(--cyan2);border-color:var(--cyan)">https://timetable.school.example/view</div><span class="tag">Fictional example</span></article></div><div class="callout" style="margin-top:17px">All domains are fictional examples and do not link to real services. HTTPS alone does not guarantee that a site is trustworthy. Independently navigate to a known official service.</div><div style="margin-top:16px">${renderQuestion(questions.links[0])}</div></section>${footerNav()}`;}
  function renderSuspects(){return `${heading('PERSONS OF INTEREST / FAIR ASSESSMENT','Suspect investigation','Review each profile and assess what the evidence actually supports. Knowing Alex, receiving a message, or having technical skills is not proof of guilt.')}<div class="grid four">${suspects.map((s,i)=>`<article class="suspect-card"><div class="suspect-avatar">${s.initials}</div><div class="eyebrow">PROFILE 0${i+1}</div><h3 style="margin:5px 0 2px">${escapeHTML(s.name)}</h3><p class="tiny muted">${escapeHTML(s.role)}</p><span class="tag ${state.suspectReview[i]?'green':''}">${escapeHTML(state.suspectReview[i]||'Not reviewed')}</span><button class="btn small" data-action="suspect" data-index="${i}">OPEN PROFILE</button></article>`).join('')}</div><div class="panel" style="margin-top:18px"><div class="panel-title"><span class="icon">⚖</span><h2>Evidence-based conclusion</h2></div><p>Use the available records to decide whether the incident is suspicious and whether they identify a responsible person.</p>${renderQuestion(questions.suspects[0])}<div class="callout warning">Do not mark a person guilty based on association or technical knowledge. The unidentified actor is only a possible explanation, not a confirmed identity.</div></div>${footerNav()}`;}
  function connectionKey(a,b){return [a,b].sort().join('-');}
  function renderBoard(){const active=state.boardSelected;return `${heading('CASE ANALYSIS / DETECTIVE BOARD','Detective evidence board','Select one card, then another to connect them. Make the five supported relationships; incorrect attempts can be retried.')}<section class="panel"><div class="callout board-help">Connect A → B → C → D → E in the event sequence. Connect F to “Context — not proof of guilt.” Each correct relationship is worth 4 points, up to 20 points. Points are awarded when you check the board.</div><div class="board-grid">${boardItems.map(item=>{const connected=state.boardConnections.some(k=>k===connectionKey(item.id,'CTX')||requiredPairs.some(pair=>connectionKey(...pair)===k&&pair.includes(item.id)));return `<button class="board-card ${active===item.id?'selected':''} ${connected?'connected':''}" data-action="board-card" data-id="${item.id}" aria-pressed="${active===item.id}"><strong>${item.id==='CTX'?'CONTEXT CATEGORY':'EVIDENCE '+item.id}</strong><h3>${escapeHTML(item.name)}</h3><p>${escapeHTML(item.desc)}</p></button>`}).join('')}</div><div class="feedback info" role="status">${active?`Selected ${escapeHTML(active)}. Choose the card it relates to.`:'Select two cards to add a relationship.'} ${state.feedback.board?escapeHTML(state.feedback.board):''}</div><div class="connection-list">${state.boardConnections.length?state.boardConnections.map(k=>`<span class="connection-chip">✓ ${escapeHTML(k.replace('-',' ↔ '))}</span>`).join(''):'<span class="muted tiny">No connections made yet</span>'}</div><div class="button-row"><button class="btn" data-action="reset-board">RESET CONNECTIONS</button><button class="btn primary" data-action="check-board">${state.boardChecked?'UPDATE BOARD SCORE':'CHECK EVIDENCE BOARD'}</button></div>${state.boardChecked?`<div class="feedback ${state.boardConnections.length===5?'success':'info'}" style="margin-top:14px"><strong>${state.boardConnections.length}/5 supported relationships connected · ${Math.round(state.boardConnections.length*4)}/20 points.</strong> The sequence supports a possible account-compromise investigation but does not prove the exact initial access method or identify the attacker.</div>`:''}</section>${footerNav()}`;}
  const timeline=[['8:42 AM','Alex receives the suspicious email.'],['8:47 AM','Alex and Jordan discuss the message.'],['8:53 AM','An unfamiliar sign-in is recorded.'],['8:56 AM','Account settings are viewed.'],['9:05 AM','The project file is accessed.'],['9:12 AM','School IT secures the account.']];
  function renderReconstruction(){return `${heading('CASE ANALYSIS / EVENT RECONSTRUCTION','Final incident reconstruction','Arrange the known events into a defensible explanation. The recorded timeline is chronological.')}<section class="panel"><div class="panel-title"><span class="icon">⌁</span><h2>Confirmed event timeline</h2></div><div class="timeline">${timeline.map(([time,detail])=>`<div class="timeline-item"><strong>${time}</strong><p>${escapeHTML(detail)}</p></div>`).join('')}</div><div class="callout warning">A timeline can show what happened and when. It does not by itself establish who caused an event or exactly how initial access occurred.</div></section><div style="margin-top:16px;display:grid;gap:14px">${renderQuestionGroup('reconstruction')}</div>${footerNav()}`;}
  const recOptions=[
    'Reset the affected password using the school\'s official process and ensure it is unique.',
    'Enable multi-factor authentication where supported.',
    'Preserve the suspicious email and relevant logs for authorized investigation.',
    'Share the password with classmates.',
    'Ignore future login alerts.',
    'Reuse the same password on every school account.'
  ];
  function renderRecommendations(){return `${heading('RESPONSE PLANNING / SECURITY ACTIONS','Security recommendation challenge','Select exactly three actions that would help contain the incident and reduce future risk.')}<section class="panel"><div class="panel-title"><span class="icon">⛨</span><h2>Choose three recommended actions</h2></div><p class="muted">Correct actions are worth 5 points each. Unsafe selections receive an explanation and no points.</p><div class="grid two">${recOptions.map((text,i)=>`<label class="check-option"><input type="checkbox" data-action="recommendation-choice" value="${i+1}" ${state.recommendationChoice.includes(i+1)?'checked':''} ${state.recommendationSubmitted?'disabled':''}><span><span class="eyebrow">OPTION ${i+1}</span><br>${escapeHTML(text)}</span></label>`).join('')}</div><div class="feedback info" style="margin-top:15px">${state.recommendationSubmitted?`Submission recorded: ${state.recommendationChoice.length} selected, ${state.recommendationChoice.filter(n=>[1,2,3].includes(n)).length} appropriate.`:'Choose exactly three options before submitting.'}</div><div class="button-row" style="margin-top:15px"><button class="btn primary" data-action="submit-recommendations" ${state.recommendationSubmitted?'disabled':''}>SUBMIT RECOMMENDATIONS</button></div>${state.recommendationSubmitted?`<div class="feedback success" style="margin-top:15px"><strong>Why these protections matter</strong><ul class="list-clean"><li>A unique password reduces the risk from password reuse.</li><li>Multi-factor authentication adds another layer of protection.</li><li>Preserving evidence supports an accurate investigation.</li><li>Reporting suspicious messages allows the school IT team to respond.</li><li>Reviewing active sessions and security settings helps identify and contain unauthorized access.</li></ul>${state.recommendationChoice.filter(n=>![1,2,3].includes(n)).length?`<p><strong>Unsafe selection note:</strong> Sharing passwords, ignoring alerts, and reusing passwords increase risk. These choices did not earn points.</p>`:''}<strong>Score awarded: ${state.recommendationChoice.filter(n=>[1,2,3].includes(n)).length*5}/15.</strong></div>`:''}</section>${footerNav('← Review evidence','GENERATE FINAL CASE REPORT →')}`;}
  function rankInfo(p){if(p>=90)return ['ELITE CYBER INVESTIGATOR','Excellent work. You connected the evidence carefully, recognized the warning signs, and made responsible security recommendations.'];if(p>=75)return ['ADVANCED INVESTIGATOR','Strong investigation. You identified most important clues and made sound decisions. Review the missed questions to strengthen your reasoning.'];if(p>=50)return ['DEVELOPING INVESTIGATOR','You uncovered several important clues. Review the security lessons and investigate the relationship between events more carefully.'];return ['INVESTIGATION TRAINING REQUIRED','Every investigation is a learning opportunity. Review the evidence, revisit the field guide, and try the case again.'];}
  function reviewTopics(){const missed=[];Object.values(questions).flat().forEach(q=>{if(state.answers[q.id]&&!state.answers[q.id].correct)missed.push(q.text);});if(state.boardChecked&&state.boardConnections.length<5)missed.push('Connecting the supported evidence relationships');if(state.recommendationSubmitted&&state.recommendationChoice.filter(n=>[1,2,3].includes(n)).length<3)missed.push('Security recommendations');return missed;}
  function renderReport(){const p=percent(),[rank,feedback]=rankInfo(p),stats=questionStats(),linked=state.boardConnections.length;return `${heading('CASE FILE / FINAL REPORT','Final investigation report','Case findings are based on the fictional evidence you inspected and the conclusions you selected.')}<section class="panel"><div class="grid two"><div><div class="eyebrow">TRACE: A DIGITAL CASE</div><h2 style="font-size:1.65rem;margin:7px 0 2px">FINAL INVESTIGATION REPORT</h2><p class="muted">Case TR-2048 · Alex Morgan</p><span class="tag green">Account secured; findings recorded</span></div><div style="text-align:right"><div class="rank">${rank}</div><div class="score-number">${formatScore()} <span class="muted" style="font-size:1rem">/ 200</span></div><div class="muted">Accuracy percentage: ${p}% · ${stats.correct}/${stats.total} correct answers</div></div></div><div class="divider"></div><div class="grid three"><div><span class="eyebrow">CASE ID</span><br><strong>TR-2048</strong></div><div><span class="eyebrow">AFFECTED USER</span><br><strong>Alex Morgan</strong></div><div><span class="eyebrow">COMPLETED STAGES</span><br><strong>${state.completed.length} / ${STAGES.length}</strong></div></div><div class="report-section"><h2>1. INCIDENT SUMMARY</h2><p>A suspicious verification email reached Alex at 8:42 AM. An unfamiliar successful sign-in was recorded at 8:53 AM, followed by account settings activity at 8:56 AM and access to Science_Project_Final.pdf at 9:05 AM. School IT secured the account at 9:12 AM by revoking active sessions and resetting the password.</p></div><div class="report-section"><h2>2. KEY EVIDENCE</h2>${state.evidence.length?`<ul class="list-clean">${state.evidence.map(id=>`<li><strong>${escapeHTML(evidenceInfo[id].title)}:</strong> ${escapeHTML(evidenceInfo[id].description)}</li>`).join('')}</ul>`:'<p>No evidence items were collected.'}<p><strong>Board connections:</strong> ${linked}/5 supported relationships · ${linked*4}/20 points.</p>${linked?`<p class="tiny muted">${state.boardConnections.map(k=>escapeHTML(k.replace('-',' ↔ '))).join(' · ')}</p>`:''}</div><div class="report-section"><h2>3. MOST LIKELY EXPLANATION</h2><p>The event sequence is consistent with a possible phishing-related account compromise. The available fictional logs do not establish the exact entry method or identify the attacker.</p><p><strong>Player’s selected conclusion:</strong> ${state.answers.recon1?escapeHTML(questions.reconstruction[0].opts[state.answers.recon1.selected]):'No conclusion answer recorded.'}</p></div><div class="report-section"><h2>4. SECURITY RECOMMENDATIONS</h2><ul class="list-clean"><li>Use a unique password and reset the affected password through the school's official process.</li><li>Enable multi-factor authentication where supported.</li><li>Independently verify unexpected emails using a known official channel.</li><li>Report suspicious messages and unfamiliar login alerts promptly.</li><li>Review active sessions and security settings, and preserve relevant evidence.</li></ul><p class="tiny muted">Recommendation challenge: ${state.recommendationChoice.filter(n=>[1,2,3].includes(n)).length}/3 appropriate actions selected · ${state.recommendationChoice.filter(n=>[1,2,3].includes(n)).length*5}/15 points.</p></div><div class="report-section"><h2>5. INVESTIGATOR PERFORMANCE</h2><p><strong>${formatScore()}/200 points (${p}%).</strong> ${stats.correct}/${stats.total} answered questions correct; ${state.evidence.length} evidence items collected; ${state.completed.length}/${STAGES.length} stages completed.</p><p><strong>Review topics:</strong> ${reviewTopics().length?reviewTopics().map(escapeHTML).join(' · '):'No missed answers recorded. Keep verifying assumptions against evidence.'}</p><p>${escapeHTML(feedback)}</p></div><div class="report-section"><h2>6. CASE CONCLUSION</h2><div class="report-quote">The available evidence supports investigating a suspected account compromise potentially associated with a phishing attempt. An unfamiliar successful sign-in was followed by account-settings activity and access to a school project file. The available records do not conclusively establish how the account was compromised or who performed the activity. The account was secured by the school IT team, and further conclusions would require verification of additional authorized records.</div></div><div class="button-row" style="margin-top:19px"><button class="btn" data-action="review-evidence">REVIEW EVIDENCE</button><button class="btn" data-action="guide">VIEW CYBERSECURITY FIELD GUIDE</button><button class="btn" data-action="download">DOWNLOAD CASE REPORT</button><button class="btn danger" data-action="restart">RESTART INVESTIGATION</button></div></section>`;}
  function openModal(title,body){modalRoot.innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><div class="eyebrow">TRACE / CASE FILE</div><h2 id="modal-title">${escapeHTML(title)}</h2></div><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button></div>${body}</section></div>`;modalRoot.querySelector('.modal-close').focus();}
  function openGuide(){const entries=[['Phishing','A deceptive message that impersonates a trusted person or organization to pressure someone into revealing information or taking an unsafe action. Check unexpected requests independently.'],['Strong passwords','Use long, unique passwords or passphrases. Never reuse them across accounts; a password manager can help create and store unique passwords.'],['Multi-factor authentication','MFA adds another verification step beyond a password, making an account harder to access with a password alone.'],['Suspicious links','Check the destination and context. A familiar display name or HTTPS does not guarantee safety. Navigate independently to a known official service.'],['Login history','Review sign-in times, devices, locations, and active sessions through the official account security system. Report activity you do not recognize.'],['Social engineering','A tactic that manipulates people through urgency, fear, trust, or authority. Pause and verify surprising requests through a separate trusted channel.'],['Reporting incidents','Promptly tell an authorized teacher or school IT team. Preserve messages and relevant records; do not publicly accuse others or spread suspicious links.']];openModal('Cybersecurity field guide',`<div class="guide-list">${entries.map(([h,p])=>`<article class="guide-item"><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><p class="footnote">Practical guidance for this fictional training investigation. Follow your school’s official security procedures.</p>`);}
  function openHow(){openModal('How to play',`<div class="callout">You are a cyber investigator examining a suspicious digital incident. Explore the available evidence, solve puzzles, investigate suspects, and connect the clues. Your final conclusion must be supported by evidence. Earn points for correct answers, careful reasoning, and appropriate security recommendations.</div><h3 style="margin-top:18px">Investigation controls</h3><ul class="list-clean"><li>Inspect every evidence-room category to unlock the investigation.</li><li>Progress through the stages in order; completed stages remain available to revisit.</li><li>Choose an answer once per question. Correct answers award points only once.</li><li>Connect evidence cards on the board, then check your relationships for partial credit.</li><li>Evidence and score save automatically in this browser. Restart clears this case session.</li></ul>`);}
  function openEvidenceModal(id){const item=evidenceInfo[id];if(!item)return;openModal(item.title,`<p>${escapeHTML(item.description)}</p><div class="callout">${escapeHTML(item.why)}</div><p class="tiny muted" style="margin-top:13px">This is a fictional case record. It does not identify a person responsible by itself.</p><div class="button-row"><button class="btn primary" data-action="modal-collect" data-id="${id}">${has(id)?'ALREADY IN EVIDENCE':'ADD TO EVIDENCE COLLECTION'}</button></div>`);}
  function openSuspect(i){const s=suspects[i];openModal(`Suspect profile · ${s.name}`,`<div class="grid two"><div><div class="eyebrow">ROLE</div><p>${escapeHTML(s.role)}</p><div class="eyebrow">POSSIBLE CONNECTION</div><p>${escapeHTML(s.connection)}</p><div class="eyebrow">EVIDENCE</div><p>${escapeHTML(s.evidence)}</p></div><div><div class="eyebrow">ADDITIONAL DETAIL</div><p>${escapeHTML(s.detail)}</p><div class="callout warning">${escapeHTML(s.note)}</div></div></div><div class="divider"></div><div class="eyebrow">YOUR EVIDENCE STATUS</div><div class="button-row" style="margin-top:10px">${['Supported by evidence','Insufficient evidence','Requires further investigation'].map(value=>`<button class="btn small ${state.suspectReview[i]===value?'primary':''}" data-action="suspect-status" data-index="${i}" data-status="${escapeHTML(value)}">${escapeHTML(value)}</button>`).join('')}</div><p class="footnote">Selecting a status is an investigation note only. It does not label a person guilty or affect points.</p>`);}
  function addEvidence(id){if(!evidenceInfo[id])return false;if(!has(id)){state.evidence.push(id);save();return true;}return false;}
  function setFeedback(text,type='info'){state.feedback.current={text,type};}
  function award(points){state.score=Math.min(CASE_TOTAL,state.score+points);}
  function completeStage(){if(!state.completed.includes(state.stage))state.completed.push(state.stage);if(state.stage<STAGES.length-1)state.stage++;if(state.stage===STAGES.length-1&&!state.completed.includes(state.stage))state.completed.push(state.stage);save();render();window.scrollTo({top:0,behavior:'smooth'});}
  function onAnswer(qid,choice){const q=Object.values(questions).flat().find(x=>x.id===qid);if(!q||state.answers[qid])return;const correct=Number(choice)===q.key;state.answers[qid]={selected:Number(choice),correct};if(correct)award(q.points);save();render();const el=app.querySelector(`[data-question="${qid}"]`);if(el)el.scrollIntoView({block:'nearest',behavior:'smooth'});}
  function completePrereqs(){if(state.stage===1&&state.roomInspected.length<5)return false;if(state.stage===10&&!state.recommendationSubmitted)return false;return true;}
  function next(){if(!completePrereqs()){if(state.stage===1)openModal('Evidence room incomplete','<p>Inspect all five case categories before continuing to the email investigation.</p>');else openModal('Recommendation challenge incomplete','<p>Submit your three security recommendations before generating the final report.</p>');return;}const groupByStage={2:'email',3:'messages',4:'logs',5:'password',6:'links',7:'suspects',9:'reconstruction'};const group=groupByStage[state.stage];if(group&&questions[group].some(q=>!state.answers[q.id])){openModal('Investigation questions remain','<p>Answer each question in this stage before continuing. Incorrect answers still count as completed; review the explanation and continue your investigation.</p>');return;}if(state.stage===8&&!state.boardChecked){openModal('Evidence board not checked','<p>Check your evidence board before continuing. Supported connections earn partial credit, and you can continue even if some relationships are missing.</p>');return;}completeStage();}
  function normalizePair(a,b){return connectionKey(a,b);}
  function handleBoardCard(id){if(!state.boardSelected){state.boardSelected=id;state.feedback.board='';save();render();return;}const first=state.boardSelected;state.boardSelected=null;if(first===id){state.feedback.board='Select a different card to make a connection.';render();return;}const key=normalizePair(first,id),valid=requiredPairs.some(pair=>normalizePair(...pair)===key);if(valid){if(!state.boardConnections.includes(key))state.boardConnections.push(key);state.feedback.board='Supported relationship added.';}else state.feedback.board='That relationship is not supported by the available evidence. Try a different pair.';save();render();}
  function checkBoard(){const score=Math.round(state.boardConnections.length*4);if(score>state.boardAwarded)award(score-state.boardAwarded);state.boardAwarded=score;state.boardChecked=true;save();render();}
  function resetBoard(){if(state.boardAwarded)state.score=Math.max(0,state.score-state.boardAwarded);state.boardAwarded=0;state.boardChecked=false;state.boardConnections=[];state.boardSelected=null;state.feedback.board='Connections reset. Rebuild the relationships and check the board.';save();render();}
  function submitRecommendations(){if(state.recommendationSubmitted)return;const selected=state.recommendationChoice;if(selected.length!==3){openModal('Choose exactly three actions',`<p>You have selected ${selected.length}. Select exactly three options, then submit your recommendations.</p>`);return;}const score=selected.filter(n=>[1,2,3].includes(n)).length*5;award(score);state.recommendationSubmitted=true;save();render();}
  function recommendationChanged(input){const n=Number(input.value);if(input.checked){if(state.recommendationChoice.length>=3){input.checked=false;openModal('Three selections maximum','<p>Uncheck an option before selecting a different action. Choose exactly three recommendations.</p>');return;}state.recommendationChoice.push(n);}else state.recommendationChoice=state.recommendationChoice.filter(x=>x!==n);save();}
  function downloadReport(){const p=percent(),[rank]=rankInfo(p),stats=questionStats(),lines=['TRACE: A DIGITAL CASE','FINAL INVESTIGATION REPORT','Case ID: TR-2048','Affected user: Alex Morgan','Case status: Account secured; investigation findings recorded.',`Player rank: ${rank}`,`Final score: ${formatScore()} / 200`,`Accuracy percentage: ${p}%`,'',`Questions completed: ${stats.total}; correct answers: ${stats.correct}`,`Completed stages: ${state.completed.length} / ${STAGES.length}`,'','COLLECTED EVIDENCE',...(state.evidence.length?state.evidence.map(id=>`- ${evidenceInfo[id].title}: ${evidenceInfo[id].description}`):['- No evidence collected']), '',`Evidence connections (${state.boardConnections.length}/5):`,...(state.boardConnections.length?state.boardConnections.map(k=>`- ${k.replace('-',' ↔ ')}`):['- No connections recorded']),'','SELECTED CONCLUSION',`Player selection: ${state.answers.recon1?questions.reconstruction[0].opts[state.answers.recon1.selected]:'No conclusion answer recorded.'}`,'The available evidence supports investigating a suspected account compromise potentially associated with a phishing attempt. An unfamiliar successful sign-in was followed by account-settings activity and access to a school project file. The available records do not conclusively establish how the account was compromised or who performed the activity. The account was secured by the school IT team, and further conclusions would require verification of additional authorized records.','','SECURITY RECOMMENDATIONS','- Use a unique password and reset the affected password through the school’s official process.','- Enable multi-factor authentication where supported.','- Independently verify unexpected emails using a known official channel.','- Report suspicious messages and unfamiliar login alerts promptly.','- Review active sessions and security settings, and preserve relevant evidence.','','All users, messages, domains, and logs in this training case are fictional.'];const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='TRACE-TR-2048-case-report.txt';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function restart(){try{localStorage.removeItem(STORAGE_KEY);}catch{}state=initialState();modalRoot.innerHTML='';render();window.scrollTo({top:0,behavior:'smooth'});}
  function onClick(event){const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='backdrop'&&event.target!==el)return;switch(action){case'start':state.started=true;if(state.stage===11&&!state.completed.includes(11))state.stage=highestUnlocked();save();render();break;case'home':event.preventDefault();openModal('Investigation in progress','<p>Your investigation is saved in this browser. Use the stage navigation to review completed evidence or the report restart button to clear the case.</p><div class="button-row"><button class="btn primary" data-action="close-modal">RETURN TO CASE</button><button class="btn danger" data-action="restart">RESTART CASE</button></div>');break;case'how':openHow();break;case'guide':openGuide();break;case'close-modal':modalRoot.innerHTML='';break;case'backdrop':modalRoot.innerHTML='';break;case'next':next();break;case'previous':if(state.stage>0){state.stage--;save();render();window.scrollTo({top:0,behavior:'smooth'});}break;case'goto':{const i=Number(el.dataset.stage);if(i<=highestUnlocked()){state.stage=i;save();render();window.scrollTo({top:0,behavior:'smooth'});}break;}case'inspect-room':{const id=el.dataset.id;if(!state.roomInspected.includes(id))state.roomInspected.push(id);const evidenceId=id==='inbox'?'email':id==='account'?'login':id==='records'?'file':id==='notes'?'notes':'messages';addEvidence(evidenceId);save();render();openEvidenceModal(evidenceId);break;}case'log-challenge':if(state.logChallenge){state.logChallenge=false;state.logOrder=[];state.logFeedback='';}else{state.logChallenge=true;state.logOrder=[5,4,3,2,1,0];state.logFeedback='';}save();render();break;case'move-log':{const position=Number(el.dataset.position),target=position+Number(el.dataset.direction);if(state.logChallenge&&target>=0&&target<state.logOrder.length){[state.logOrder[position],state.logOrder[target]]=[state.logOrder[target],state.logOrder[position]];state.logFeedback='';save();render();}break;}case'check-log-order':state.logFeedback=state.logOrder.every((value,index)=>value===index)?'Correct — all six fictional records are in chronological order.':'Not yet — compare each timestamp and adjust the records. This challenge does not change your score.';save();render();break;case'collect':{const id=el.dataset.id;addEvidence(id);render();break;}case'modal-collect':{const id=el.dataset.id;addEvidence(id);modalRoot.innerHTML='';render();break;}case'answer':onAnswer(el.dataset.question,el.dataset.choice);break;case'suspect':openSuspect(Number(el.dataset.index));break;case'suspect-status':state.suspectReview[el.dataset.index]=el.dataset.status;save();openSuspect(Number(el.dataset.index));render();break;case'board-card':handleBoardCard(el.dataset.id);break;case'check-board':checkBoard();break;case'reset-board':resetBoard();break;case'submit-recommendations':submitRecommendations();break;case'download':downloadReport();break;case'review-evidence':state.stage=1;save();render();break;case'restart':restart();break;}}
  app.addEventListener('click',onClick);modalRoot.addEventListener('click',onClick);app.addEventListener('change',event=>{if(event.target.matches('[data-action="recommendation-choice"]'))recommendationChanged(event.target);});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modalRoot.innerHTML)modalRoot.innerHTML='';});
  render();
})();